def batch(items):
    p="/tmp/b.json"
    with open(p,"w") as f:
        for n,a in items:
            f.write(json.dumps({"name":n,"arguments":a})+"\n")
    r=subprocess.run(["ft2","batch",p],capture_output=True,text=True)
    if r.returncode!=0: print("BATCH ERR",r.stdout[:2000],r.stderr[:2000])
    return r.stdout

